    var rules = [
        {
            breakpoint: 576,
            options: {
                chart: { height: 260 },
                legend: { fontSize: "11px" }
            }
        },
        {
            breakpoint: 768,
            options: {
                chart: { height: 280 }
            }
        }
    ];
    var i;
    if (extra && extra.length) {
        for (i = 0; i < extra.length; i++) {
            rules.push(extra[i]);
        }
    }
    return rules;
}

