function buildHorizontalBarOptions(labels, series, seriesName, chartHeight, useDistributed, isFullscreen, xAxisTitle, tooltipUnit) {
    var labelCount = labels ? labels.length : 0;
    var axisTitle = xAxisTitle || "Sinh viên";
    var unitLabel = tooltipUnit || "sinh viên";
    return {
        series: [{ name: seriesName || "Số lượng", data: series }],
        chart: Object.assign({ height: chartHeight, type: "bar" }, baseChartOpts),
        plotOptions: {
            bar: {
                horizontal: true,
                borderRadius: 6,
                barHeight: isFullscreen ? "78%" : (labelCount > 8 ? "72%" : "65%"),
                distributed: useDistributed === true
            }
        },
        colors: useDistributed === true ? CHART_PALETTE : [PRIMARY],
        dataLabels: {
            enabled: true,
            style: { colors: ["#fff"], fontSize: isFullscreen ? "12px" : "11px", fontWeight: 600 }
        },
        xaxis: {
            categories: labels,
            title: { text: axisTitle },
            labels: {
                formatter: function (val) { return formatNumber(val); },
                style: { fontSize: isFullscreen ? "12px" : "11px" }
            }
        },
        yaxis: {
            labels: { maxWidth: isFullscreen ? 360 : 180, style: { fontSize: isFullscreen ? "12px" : "11px" } }
        },
        grid: { strokeDashArray: 4, borderColor: "#e2e8f0", padding: { right: isFullscreen ? 24 : 8 } },
        legend: { show: false },
        tooltip: {
            y: { formatter: function (val) { return formatNumber(val) + " " + unitLabel; } }
        }
    };
}

