function registerFullscreen(key, title, optionsBuilder, layoutMode) {
    fullscreenStates[key] = {
        title: title,
        optionsBuilder: optionsBuilder,
        layoutMode: layoutMode || "horizontal"
    };
    var btnMap = {
        topGraduated: "sgdDashBtnFullscreenTopGraduated",
        topNotGraduated: "sgdDashBtnFullscreenTopNotGraduated",
        byCourse: "sgdDashBtnFullscreenByCourse",
        byScience: "sgdDashBtnFullscreenByScience",
        classStack: "sgdDashBtnFullscreenClassStack"
    };
    var btn = getEl(btnMap[key]);
    if (btn) {
        btn.disabled = false;
    }
}

function buildClassLineSeries(rows, limit) {
    var sliced = sliceTopRows(rows, "TotalCount", limit, true);
    var labels = [];
    var eligibleSeries = [];
    var notEligibleSeries = [];
    var i;
    for (i = 0; i < sliced.items.length; i++) {
        labels.push(sliced.items[i].ClassName || "");
        eligibleSeries.push(parseInt(sliced.items[i].EligibleCount, 10) || 0);
        notEligibleSeries.push(parseInt(sliced.items[i].NotEligibleCount, 10) || 0);
    }
    return {
        labels: labels,
        eligibleSeries: eligibleSeries,
        notEligibleSeries: notEligibleSeries,
        total: sliced.total
    };
}

function renderEligibleOverview(summaryRows) {
    var summary = (summaryRows && summaryRows.length > 0) ? summaryRows[0] : {};
    var isEmpty = !summary.TotalReviewStudent;
    renderChart(
        "#sgdDashChartEligibleDonut",
        isEmpty ? { isEmpty: true } : buildRadialRateOptions(summary.GraduationRate, "Tỷ lệ đủ ĐK TN"),
        "sgdDashChartEligibleDonutEmpty"
    );
}

function renderTopGraduatedChart(rows) {
    var sliced = sliceTopRows(rows, "EligibleCount", TOP_LIMIT, true);
    var labels = [];
    var series = [];
    var i;
    for (i = 0; i < sliced.items.length; i++) {
        labels.push(sliced.items[i].ClassName || "");
        series.push(parseInt(sliced.items[i].EligibleCount, 10) || 0);
    }
    var isEmpty = series.length === 0;
    setChartPreviewNote("sgdDashChartTopGraduatedNote", sliced.total, TOP_LIMIT);
    setScrollWrapHeight(getEl("sgdDashChartTopGraduatedScroll"), labels.length, 36);
    renderChart(
        "#sgdDashChartTopGraduated",
        isEmpty ? { isEmpty: true } : buildModernLineOptions(
            labels,
            [{ name: "Đủ ĐK TN", data: series }],
            320,
            false,
            "Sinh viên",
            function (val) { return formatNumber(val) + " sinh viên"; }
        ),
        "sgdDashChartTopGraduatedEmpty"
    );

    if (!isEmpty) {
        registerFullscreen("topGraduated", "Top lớp — tốt nghiệp cao nhất (toàn bộ)", function () {
            var allSliced = sliceTopRows(rows, "EligibleCount", 0, true);
            var allLabels = [];
            var allSeries = [];
            var j;
            for (j = 0; j < allSliced.items.length; j++) {
                allLabels.push(allSliced.items[j].ClassName || "");
                allSeries.push(parseInt(allSliced.items[j].EligibleCount, 10) || 0);
            }
            return buildModernLineOptions(
                allLabels,
                [{ name: "Đủ ĐK TN", data: allSeries }],
                Math.max(420, allLabels.length * 28 + 120),
                true,
                "Sinh viên",
                function (val) { return formatNumber(val) + " sinh viên"; }
            );
        }, "line");
    }
}

function renderTopNotGraduatedChart(rows) {
    var sliced = sliceTopRows(rows, "NotEligibleCount", TOP_LIMIT, true);
    var labels = [];
    var series = [];
    var i;
    for (i = 0; i < sliced.items.length; i++) {
        labels.push(sliced.items[i].ClassName || "");
        series.push(parseInt(sliced.items[i].NotEligibleCount, 10) || 0);
    }
    var isEmpty = series.length === 0 || series.every(function (v) { return v === 0; });
    setChartPreviewNote("sgdDashChartTopNotGraduatedNote", sliced.total, TOP_LIMIT);
    setScrollWrapHeight(getEl("sgdDashChartTopNotGraduatedScroll"), labels.length, 36);
    renderChart(
        "#sgdDashChartTopNotGraduated",
        isEmpty ? { isEmpty: true } : buildModernAreaOptions(
            labels,
            [{ name: "Chưa đủ ĐK TN", data: series }],
            320,
            false,
            [DANGER],
            "Sinh viên",
            function (val) { return formatNumber(val) + " sinh viên"; }
        ),
        "sgdDashChartTopNotGraduatedEmpty"
    );

    if (!isEmpty) {
        registerFullscreen("topNotGraduated", "Top lớp — chưa đủ điều kiện TN (toàn bộ)", function () {
            var allSliced = sliceTopRows(rows, "NotEligibleCount", 0, true);
            var allLabels = [];
            var allSeries = [];
            var j;
            for (j = 0; j < allSliced.items.length; j++) {
                allLabels.push(allSliced.items[j].ClassName || "");
                allSeries.push(parseInt(allSliced.items[j].NotEligibleCount, 10) || 0);
            }
            return buildModernAreaOptions(
                allLabels,
                [{ name: "Chưa đủ ĐK TN", data: allSeries }],
                Math.max(420, allLabels.length * 28 + 120),
                true,
                [DANGER],
                "Sinh viên",
                function (val) { return formatNumber(val) + " sinh viên"; }
            );
        }, "line");
    }
}

function renderByCourseChart(rows) {
    var labels = [];
    var series = [];
    var i;
    for (i = 0; i < rows.length; i++) {
        labels.push(rows[i].CourseName || "");
        series.push(parseFloat(rows[i].GraduationRate) || 0);
    }
    var previewLabels = labels;
    var previewSeries = series;
    var total = labels.length;
    if (total > TOP_LIMIT) {
        previewLabels = labels.slice(0, TOP_LIMIT);
        previewSeries = series.slice(0, TOP_LIMIT);
    }
    var isEmpty = previewSeries.length === 0;
    setChartPreviewNote("sgdDashChartByCourseNote", total, TOP_LIMIT);
    renderChart(
        "#sgdDashChartByCourse",
        isEmpty ? { isEmpty: true } : buildRateLineOptions(previewLabels, previewSeries, 320, false),
        "sgdDashChartByCourseEmpty"
    );

    if (!isEmpty) {
        registerFullscreen("byCourse", "Tỷ lệ tốt nghiệp theo khóa (toàn bộ)", function () {
            return buildRateLineOptions(labels, series, Math.max(400, labels.length * 36 + 100), true);
        }, "line");
    }
}

function renderGraduationLevelChart(rows) {
    var labels = [];
    var series = [];
    var i;
    for (i = 0; i < rows.length; i++) {
        labels.push(rows[i].GraduationLevel || "");
        series.push(parseInt(rows[i].StudentCount, 10) || 0);
    }
    var isEmpty = series.length === 0;
    renderChart(
        "#sgdDashChartGraduationLevel",
        isEmpty ? { isEmpty: true } : buildRadarOptions(labels, series),
        "sgdDashChartGraduationLevelEmpty"
    );
}

function renderByScienceChart(rows) {
    var sliced = sliceTopRows(rows, "TotalCount", TOP_LIMIT, true);
    var labels = [];
    var series = [];
    var i;
    for (i = 0; i < sliced.items.length; i++) {
        labels.push(sliced.items[i].ScienceName || "");
        series.push(parseFloat(sliced.items[i].GraduationRate) || 0);
    }
    var isEmpty = series.length === 0;
    setChartPreviewNote("sgdDashChartByScienceNote", sliced.total, TOP_LIMIT);
    setScrollWrapHeight(getEl("sgdDashChartByScienceScroll"), labels.length, 36);
    renderChart(
        "#sgdDashChartByScience",
        isEmpty ? { isEmpty: true } : buildRateLineOptions(labels, series, 320, false),
        "sgdDashChartByScienceEmpty"
    );

    if (!isEmpty) {
        registerFullscreen("byScience", "Thống kê theo khoa / ngành (toàn bộ)", function () {
            var allLabels = [];
