function resetScrollWrap(wrapEl) {
    if (!wrapEl) {
        return;
    }
    wrapEl.style.maxHeight = "";
    wrapEl.style.overflowY = "visible";
}

function setScrollWrapHeight(wrapEl, itemCount, rowHeight) {
    if (!wrapEl) {
        return;
    }
    var maxHeight = 420;
    var minHeight = 280;
    var calculated = itemCount * rowHeight + 48;
    var height = calculated > maxHeight ? maxHeight : calculated;
    if (height < minHeight) {
        height = minHeight;
    }
    wrapEl.style.maxHeight = height + "px";
    wrapEl.style.overflowY = itemCount * rowHeight + 48 > maxHeight ? "auto" : "visible";
}

