function renderByCourseLineChart(rows) {
    var labels = [];
    var series = [];
    var i;
    for (i = 0; i < rows.length; i++) {
        labels.push(rows[i].CourseName || "");
        series.push(parseFloat(rows[i].GraduationRate) || 0);
    }
    var previewLabels = labels;
    var previewSeries = series;
    var total = labels.length;
    if (total > TOP_LIMIT) {
        previewLabels = labels.slice(0, TOP_LIMIT);
        previewSeries = series.slice(0, TOP_LIMIT);
    }
    var isEmpty = previewSeries.length === 0;
    setChartPreviewNote("sgdDashChartByCourseLineNote", total, TOP_LIMIT);
    renderChart("#sgdDashChartByCourseLine", isEmpty ? { isEmpty: true } : buildRateLineOptions(previewLabels, previewSeries, 320, false), "sgdDashChartByCourseLineEmpty");

    if (!isEmpty) {
        registerFullscreen("byCourseLine", "Xu hướng tỷ lệ tốt nghiệp theo khóa (toàn bộ)", function () {
            return buildRateLineOptions(labels, series, Math.max(400, labels.length * 36 + 100), true);
        }, "line");
    }
}

function renderByScienceLineChart(rows) {
    var sliced = sliceTopRows(rows, "TotalCount", TOP_LIMIT, true);
    var labels = [];
    var series = [];
    var i;
    for (i = 0; i < sliced.items.length; i++) {
        labels.push(sliced.items[i].ScienceName || "");
        series.push(parseFloat(sliced.items[i].GraduationRate) || 0);
    }
    var isEmpty = series.length === 0;
    setChartPreviewNote("sgdDashChartByScienceLineNote", sliced.total, TOP_LIMIT);
    renderChart("#sgdDashChartByScienceLine", isEmpty ? { isEmpty: true } : buildRateLineOptions(labels, series, 320, false), "sgdDashChartByScienceLineEmpty");

    if (!isEmpty) {
        registerFullscreen("byScienceLine", "Xu hướng tỷ lệ theo khoa / ngành (toàn bộ)", function () {
            var allLabels = [];
            var allSeries = [];
            var j;
            var allSliced = sliceTopRows(rows, "TotalCount", 0, true);
            for (j = 0; j < allSliced.items.length; j++) {
                allLabels.push(allSliced.items[j].ScienceName || "");
                allSeries.push(parseFloat(allSliced.items[j].GraduationRate) || 0);
            }
            return buildRateLineOptions(allLabels, allSeries, Math.max(420, allLabels.length * 32 + 100), true);
        }, "line");
    }
}

